import "server-only";
import manifest from "./mock/ctf-artifacts.manifest.json";
import type { CtfArtifactFile } from "./mock/ctf";

/** A challenge's solvable material, generated by scripts/ctf-artifacts/: `embed` is shown
 * inline on the challenge page, `files` are downloads from public/ctf-artifacts/. Server-only
 * so it is rendered per challenge page and never shipped in a client bundle. Never contains
 * the flag -- the generator's verify step checks every flag is only recoverable by solving. */
export type CtfMaterial = { embed?: string; files?: CtfArtifactFile[] };

export function getCtfMaterial(challengeId: string): CtfMaterial {
  return (manifest as Record<string, CtfMaterial>)[challengeId] ?? {};
}
